                OTHER_KEY
            ).audit_bundle(BUNDLE_1)
        auditor = SpanBundleReceiptBatchReceiptAuditor(KEY)
        with self.assertRaises(ValueError):
            auditor.audit_bundle(
                dataclasses.replace(BUNDLE_1, signature=ZERO)
