            receipt.bundle_digest,
            hashlib.sha256(BUNDLE_FULL.to_bytes()).digest(),
        )
        self.assertEqual(receipt.end, BUNDLE_FULL.end)
        self.assertEqual(
            receipt.signature,
            _span_bundle_receipt_batch_receipt_bundle_receipt_signature(
                KEY, receipt
            ),
        )

